			<Provider devMock={{ title: "Development result" }}>
				<Probe />
			</Provider>,
		);
		expect(await screen.findByText("Cached race card")).toBeInTheDocument();
		await waitFor(() => expect(restoreCount).toBe(1));
		fireEvent.click(screen.getByRole("button", { name: "Edit during restore" }));
		await act(() => new Promise((resolve) => window.setTimeout(resolve, 300)));
		await act(async () => {
			resolveFirst({ isError: true });
			await firstRestore;
		});
		await waitFor(() => expect(restoreCount).toBeGreaterThanOrEqual(2));
		await waitFor(() =>
			expect(
				bridge.callServerTool.mock.calls.some(
					([request]) => request.name === "save_lobu_app_state",
				),
			).toBe(true),
		);
	});
});
